import{sensesFigure}from './senses-figures.js?v=20261023-physicscomplete01';
export const sensesFilms={
 'senses-light':{title:'The pupil response',steps:['Bright light: circular muscles contract and the pupil narrows.','Entering dim light: radial muscles contract and circular muscles relax.','The larger pupil admits more light.','Returning to bright light reduces pupil size again.'],note:'Front-view iris schematic; relative aperture and timing are illustrative. Lens accommodation is a separate process. The loop alternates example light conditions, rather than implying a fixed natural cycle.',duration:12,render:p=>sensesFigure({kind:'pupil',state:p<.25||p>=.75?'bright':'dim',pupilRadius:22+33*Math.sin(p*Math.PI)**2})},
 'senses-focus':{title:'Accommodation: distance to near and back',steps:['Distant object: ciliary muscles relaxed; ligaments tight; lens thin.','Near object: ciliary muscles contract and ligaments loosen.','The thicker lens refracts near-object rays more strongly onto the retina.','Return to distant focus: muscle relaxes, ligaments tighten and lens thins.'],note:'A slowed linked-state model, not measured muscle or optical timing. Near rays diverge before entering; distant rays are approximately parallel. Refraction is represented by simplified piecewise rays; the cornea also refracts light.',duration:12,render:p=>sensesFigure({kind:'accommodation',state:p>=.25&&p<.75?'near':'far',lensWidth:11+11*Math.sin(p*Math.PI)**2,progress:(p*4)%1})},
 'senses-correction':{title:'Correcting the focus',steps:['Myopia: distant-object focus lies in front of the retina.','A concave diverging spectacle lens moves the final focus onto the retina.','Hyperopia: near-object focus would lie behind the retina.','A convex converging spectacle lens moves the final focus onto the retina.'],note:'Two separate worked examples with symbolic ray paths, not a transition from one diagnosis to another. The reset returns to the first example. Positions are schematic, not calculated clinical prescriptions. Moving tracer indicates direction, not light speed.',duration:12,render:p=>sensesFigure({kind:'vision',state:p<.5?'myopia':'hyperopia',corrected:Math.floor(p*4)%2===1,progress:(p*4)%1})}
};
